

const http=require('http')
const fs=require('fs')
const port=3100;

const server=http.createServer((req,res)=>{

   if(req.method=='POST'){
    let body="";
    req.on("data",(chunk)=>{
        body+=chunk
    })
    req.on("end",()=>{
        const userData=JSON.parse(body)
        fs.readFile("./sample.js","utf-8",(err,data)=>{
            if(err){
                res.write("error occured");
                res.end()
            }
            else{
                const fileData=JSON.parse(data)
                const existing_user=fileData.find((user)=>user.name===userData.name)
                if(existing_user){
                    console.log("user already exist")
                    res.end()
                }
                else{
                    fileData.push(userData)

                    fs.writeFile("./sample.js",JSON.stringify(fileData),(error)=>{
                        if(error){
                            res.write("error occured")
                            res.end()
                        }
                        else{
                            res.write(JSON.stringify(fileData))
                            res.end()
                        }
                    })
                }
            }
        })
    })
    res.end()
   }
    else if(req.method=="GET"){
        res.end()
    }
    else if(req.method=="DELETE"){
        let userName=req.url.split("/")[1]
        fs.readFile("./sample.js","utf-8",(err,data)=>{
            if(err){
                res.end("error")
            }
            else{
                const finalData=JSON.parse(data);
                console.log(finalData,"before filrering")

                const filterData=finalData.filter((user)=>user.name!==userName);
                fs.writeFile("./sample.js",JSON.stringify(filterData),(err)=>{
                    if(err){
                        res.end("error occured")
                    }
                    else{
                        res.end(JSON.stringify(filterData))
                    }
                })
            }
        })

        res.end()
    }
    else if(req.method=="PUT" || req.method=='PATCH'){

        res.end()

    }
    else{
        res.write("Invalid method")
        res.end()
    }

})
server.listen(port,()=>{
    console.log(`server running at ${port}`)
})